import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, CircleMarker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

function MapView() {
  const [crimeData, setCrimeData] = useState([]);

  useEffect(() => {
    fetch('http://127.0.0.1:5000/api/crimes') // your Flask backend
      .then(res => res.json())
      .then(data => setCrimeData(data))
      .catch(err => console.error(err));
  }, []);

  const getColor = (type) => {
    switch(type) {
      case 'Theft': return 'red';
      case 'Assault': return 'orange';
      case 'Burglary': return 'blue';
      default: return 'green';
    }
  }

  return (
    <MapContainer center={[20.5937, 78.9629]} zoom={5} style={{ height: '100vh', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; OpenStreetMap contributors"
      />

      {crimeData.map((crime, idx) => (
        <CircleMarker
          key={idx}
          center={[crime.Latitude, crime.Longitude]}
          pathOptions={{ color: getColor(crime.Type) }}
          radius={6}
        >
          <Popup>
            <strong>{crime.Type}</strong><br />
            {crime.City}, {crime.State}
          </Popup>
        </CircleMarker>
      ))}
    </MapContainer>
  );
}

export default MapView;
